export const LIMIT=10;
export const MISSING='미확인';
export const MONEY=v=>Number.isFinite(v)?new Intl.NumberFormat('ko-KR').format(v)+'원':MISSING;
export function feeConditions(f){return [f?.per==='person'?'1인당':f?.per==='team'?'팀당':'과금단위 미확인',f?.holes?`${f.holes}홀`:'홀 기준 미확인',f?.valid_from?`${f.valid_from} 시행 (${f.effective_basis||'적용 기준 미확인'})`:'시행일 미확인',f?.taxes_included===true?'세금 포함':f?.taxes_included===false?'세금 별도':'세금 포함 여부 미확인'].join(' · ');}
export function greenFeeText(f,day){return `${f.condition||'조건 미확인'}: ${MONEY(f[day])} · ${feeConditions(f)}`;}
export function extraFeeText(f){return `${MONEY(f?.value)} · ${feeConditions(f)}`;}
export function normalizeCatalog(data){return (data.courses||[]).map(c=>({id:c.id,name:c.name.value,lat:c.coordinates?.value?.lat??null,lon:c.coordinates?.value?.lon??null,distance:null,evidence:['name','address','website','holes','phone','fee_guide','cart_fee','caddie_fee'].filter(k=>c[k]?.value!=null).length,tags:{name:c.name.value,'golf:holes':c.holes?.value,phone:c.phone?.value,website:c.website?.value},official:c}));}
export function estimateCost(c,date,partySize){const o=c.official;if(!date||!Number.isInteger(partySize)||partySize<1||partySize>4)return {text:'날짜·인원을 선택하세요',total:null};if(!o?.quote||o.quote.date!==date||o.quote.party_size!==partySize||!o.quote.all_mandatory_costs_verified)return {text:'산출 불가 · 선택일 요금·필수비·과금단위·세금 적용 미확인',total:null};const q=o.quote;const numbers=[q.green_per_person,q.extras_per_person,q.cart_per_team,q.caddie_per_team,q.tax_per_person];if(!numbers.every(v=>Number.isFinite(v)&&v>=0))return {text:'산출 불가 · 필수비 누락',total:null};const total=q.green_per_person+q.extras_per_person+(q.cart_per_team+q.caddie_per_team)/partySize+q.tax_per_person;return {text:`${MONEY(total)} / 1인 · 선택일·인원 조건`,total};}
export function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
export function validBounds(b){return b&&[b.s,b.w,b.n,b.e].every(Number.isFinite)&&b.s>=-85&&b.n<=85&&b.s<b.n&&b.w>=-180&&b.e<=180&&b.w<b.e;}
export function queryFor(b){if(!validBounds(b)||b.n-b.s>4||b.e-b.w>6)throw new Error('골프장 탐색에 맞게 지도를 확대해 주세요. 위도 4° · 경도 6° 이내 화면을 지원합니다.');return `[out:json][timeout:35];nwr["leisure"="golf_course"](${b.s},${b.w},${b.n},${b.e});out tags center;`;}
export function distanceKm(a,b){const r=Math.PI/180,d1=(b.lat-a.lat)*r,d2=(b.lon-a.lon)*r;const x=Math.sin(d1/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(d2/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(Math.max(0,1-x)));}
export function normalize(elements,b){const seen=new Set();return elements.flatMap(e=>{const lat=e.lat??e.center?.lat,lon=e.lon??e.center?.lon,t=e.tags||{};if(t.leisure!=='golf_course'||!Number.isFinite(lat)||!Number.isFinite(lon)||lat<b.s||lat>b.n||lon<b.w||lon>b.e)return [];const id=`${e.type}/${e.id}`;if(seen.has(id))return [];seen.add(id);const name=t['name:ko']||t.name||t['name:en']||'이름 미등록 골프장';return [{id,name,lat,lon,tags:t,evidence:['name','golf:holes','golf:par','website','phone','access','operator','addr:city'].filter(k=>Boolean(t[k])).length,distance:distanceKm({lat:(b.s+b.n)/2,lon:(b.w+b.e)/2},{lat,lon})}];});}
export function shortlist(items,search='',sort='evidence',limit=LIMIT){return items.filter(c=>c.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ko'):sort==='distance'?a.distance-b.distance:b.evidence-a.evidence||a.name.localeCompare(b.name,'ko')).slice(0,limit===20?20:10);}
function baseComparison(c){const t=c.tags;return [ ['분류','공개지도 골프장 후보'],['자료 출처',`OpenStreetMap ${c.id}`],['좌표',`${Number.isFinite(c.lat)?c.lat.toFixed(5):MISSING}, ${Number.isFinite(c.lon)?c.lon.toFixed(5):MISSING}`],['공식 명칭 검증','OSM 등록명 · 공식 대조 미완료'],['운영자',t.operator||MISSING],['주소',[t['addr:city'],t['addr:street'],t['addr:housenumber']].filter(Boolean).join(' ')||MISSING],['연락처',t.phone||t['contact:phone']||MISSING],['홀 수',t['golf:holes']||MISSING],['파',t['golf:par']||MISSING],['코스 유형',t.golf||MISSING],['접근 조건',t.access||MISSING],['화면 중심 직선거리',`${Number.isFinite(c.distance)?c.distance.toFixed(1):MISSING} km · 이동거리 아님`],['주중 그린피',MISSING],['주말·공휴일 그린피',MISSING],['카트비',MISSING],['캐디피',MISSING],['1인 예상 총비용','요금 근거 부족 · 산출하지 않음'],['요금 기준일·통화',MISSING],['홀·시간대별 할인',MISSING],['잔여 티타임',MISSING],['예약 방식',MISSING],['취소·환불 규정',MISSING],['대중교통 접근성',MISSING],['주차·전기차 충전',MISSING],['코스 난이도·전장',MISSING],['코스 관리·그린 상태',MISSING],['풍경·전경 사진',(c.photos||[]).some(p=>p.courseMatched===true&&p.exportAllowed===true&&p.license&&(p.courseId===c.id||(typeof p.courseName==='string'&&p.courseName===c.name))&&safeURL(p.url)&&safeURL(p.sourceUrl))?'코스 일치·사용권 확인 사진 있음 · 개별 크레딧 참조':'사용권 확인 사진 미확보'],['클럽하우스·식음료',MISSING],['연습장·렌탈',MISSING],['숙박·리조트',MISSING],['이용자 평점·후기 수','미수집 · 평점 미산정'],['평가 기간·평가 출처',MISSING],['장점','위치·OSM에 수록된 필드 확인 가능'],['확인할 점','가격·후기·운영·예약 정보 공식 대조 필요'],['공개지도 정보 충실도',`${c.evidence}/8 필드 · 코스 품질 점수 아님`],['종합 평가','자료 부족 · 순위 미산정'] ];}
export function comparison(c){const rows=baseComparison(c);if(!c.official)return rows;const o=c.official;const overrides={'분류':'공식 공개자료 초기 카탈로그','자료 출처':o.name.source_url,'좌표':Number.isFinite(c.lat)?`${Number.isFinite(c.lat)?c.lat.toFixed(5):MISSING}, ${Number.isFinite(c.lon)?c.lon.toFixed(5):MISSING} · ${o.coordinates.provider||o.coordinates.status}`:'미확인','공식 명칭 검증':'공식자료 대조','주소':o.address?.value||MISSING,'주중 그린피':o.green_fees.map(f=>greenFeeText(f,'weekday')).join(' / ')||MISSING,'주말·공휴일 그린피':o.green_fees.map(f=>greenFeeText(f,'weekend')).join(' / ')||MISSING,'카트비':extraFeeText(o.cart_fee),'캐디피':extraFeeText(o.caddie_fee),'요금 기준일·통화':`KRW · 조회 ${o.name.checked_at} · 실제 적용일 확인 필요`,'화면 중심 직선거리':Number.isFinite(c.distance)?`${Number.isFinite(c.distance)?c.distance.toFixed(1):MISSING} km · 이동거리 아님`:'지도 조회 후 표시','장점':'공식 명칭·주소·공개 안내 대조 가능','확인할 점':'선택일 요금·운영·후기·예약 조건 재확인 필요','공개지도 정보 충실도':`${c.evidence}/8 공식자료 필드 · 코스 품질 점수 아님`};return rows.map(([k,v])=>[k,overrides[k]??v]).concat([['공식 홈페이지',o.website?.value||MISSING],['공식 요금 출처',o.fee_guide?.value||MISSING],['위치 정보 출처',o.coordinates.source_url||MISSING],['자료 확인시각',o.name.checked_at],['예약 페이지',o.booking?.status==='verified'?o.booking.url:'정확한 URL 미확인 · 홈페이지 메뉴 이용']]);}
export function reportHTML(snapshot,items,sortLabel,options={}){const e=escapeHTML,b=snapshot.bounds;const cards=items.map((c,i)=>{const source=c.official?.name.source_url||`https://www.openstreetmap.org/${c.id}`;return `<section><h2>${String(i+1).padStart(2,'0')} / ${e(c.name)}</h2><p>목록 번호이며 추천 순위가 아닙니다.</p><table>${comparison(c).map(([k,v])=>`<tr><th>${e(k)}</th><td>${e(v)}</td></tr>`).join('')}</table><p><a href="${e(safeURL(source)||'#')}">자료 원본 보기</a>${safeURL(c.tags.website||c.tags['contact:website'])?` · <a href="${e(safeURL(c.tags.website||c.tags['contact:website']))}">${c.official?'공식 홈페이지':'OSM 등록 웹사이트 (공식성 미검증)'}</a>`:''}</p></section>`;}).join('');const date=options.date||'',party=Number(options.partySize)||4,chosen=(options.compareCourses||[]).slice(0,4);const plan=`<section><h2>라운드 계획 · 선택 비교</h2><p>선택 날짜: ${e(date||'미선택')} · 팀 인원: ${e(party)}명 · 비교 선택: ${chosen.length}/4곳</p>${chosen.length?`<table><thead><tr><th>코스</th><th>선택일 1인 총비용 / 사유</th><th>일반요금 참고 조건</th></tr></thead><tbody>${chosen.map(c=>`<tr><th>${e(c.name)}</th><td>${e(estimateCost(c,date,party).text)}</td><td>${e(c.official?.green_fees?.map(f=>greenFeeText(f,'weekday')+' / '+greenFeeText(f,'weekend')).join(' / ')||'요금 미확인')}<br>카트 ${e(extraFeeText(c.official?.cart_fee))}<br>캐디 ${e(extraFeeText(c.official?.caddie_fee))}</td></tr>`).join('')}</tbody></table>`:'<p>별도로 선택한 비교 코스가 없습니다.</p>'}<p>일반요금은 선택일 확정견적이 아닙니다. 모든 필수비·과금단위·세금·날짜 조건이 확인되지 않으면 총액을 산출하지 않습니다.</p></section>`;return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRI ATLAS · 골프장 비교 자료</title><style>body{font:14px/1.8 system-ui,sans-serif;color:#193f35;background:#f5f8f0;max-width:1000px;margin:auto;padding:40px}h1{font:50px Georgia,serif}section{margin:40px 0;break-inside:avoid}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border-bottom:1px solid #cddccc;padding:9px;text-align:left}th{width:35%;background:#e5eee1}a{color:#17654a}footer,p{font-size:12px}@media print{body{background:white;padding:0}section{break-before:page}}</style></head><body><header><b>FRI ATLAS / FIELD NOTES</b><h1>Your next fairway.</h1><p>후보 비교 · 순위 미산정 · 정렬: ${e(sortLabel)}</p></header><p>분석 확인시각: ${e(snapshot.time)}<br>데이터 기준시각: ${e(snapshot.dataTime||'API 미제공')}<br>자료 공급: ${snapshot.provider==='catalog'?'공식자료 초기 카탈로그 (전체목록 아님)':'OpenStreetMap / Overpass 실험 조회'}<br>스냅샷: 남 ${b.s.toFixed(5)} / 서 ${b.w.toFixed(5)} / 북 ${b.n.toFixed(5)} / 동 ${b.e.toFixed(5)}<br>수집 ${snapshot.items.length}곳 · 이 자료 표시 ${items.length}곳 · 대표점 기준. 중복 개체가 포함될 수 있습니다.<br>전경 사진은 코스별 사용권 확인 범위만 제공합니다. 가격은 공식 일반안내가 있을 때만 참고값으로 기재하며 실시간 견적이 아닙니다. 리뷰·예약은 미확인입니다.<br>종합평가 가중치: 비용30/코스30/접근성25/근거15 · 비교근거 부족으로 미산정.<br>이 파일에는 지도 스크립트가 없으며 결과를 다시 조회하지 않습니다.</p>${plan}${cards||'<p>표시할 후보가 없습니다.</p>'}<footer>출처: 각 코스 공식자료 링크 · <a href="https://www.openstreetmap.org/copyright">© OpenStreetMap contributors / ODbL</a> · <a href="https://wiki.openstreetmap.org/wiki/Overpass_API">Overpass API</a><br>요금·티타임·예약은 골프장에 직접 확인하세요. FRI ATLAS는 예약을 대행하지 않습니다.</footer></body></html>`;}
